		dic[id]={}
		dic[id]["TD"]=Thread.new()
		dic[id]["TD"].start(Callable(self,"tdr").bind(id))
		dic[id]["MT"] = Semaphore.new()

var mutex = Mutex.new()
func tdr(idid):
	OS.delay_msec(randi_range(1000,2000))
	var id = idid
	var oldtimer = timer
	while true:
		dic[id]["MT"].wait()
		if timer > oldtimer + 1000:
			printt("tdr2",id,mutex.try_lock(),timer-oldtimer)
			oldtimer = timer

var timer = 0
func _process(delta: float) -> void:
